using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RentalCamera.Data;using RentalCamera.Models;
namespace RentalCamera.Controllers;public class PhiPhatController:BaseController{private readonly RentalCameraDbContext _db;public PhiPhatController(RentalCameraDbContext db)=>_db=db;public async Task<IActionResult> Index(){var data=await (from p in _db.PhieuPhat join ct in _db.ChiTietHopDong on p.MaChiTietHopDong equals ct.MaChiTietHopDong join hd in _db.HopDong on ct.MaHopDong equals hd.MaHopDong orderby p.NgayLap descending select new PenaltyRowVM{Phieu=p,MaHopDong=hd.MaHopDong,MaThietBi=ct.MaThietBi}).ToListAsync();return View(data);}[HttpGet]public async Task<IActionResult>Create(){ViewBag.ChiTiet=await _db.ChiTietHopDong.OrderByDescending(x=>x.NgayGiaoThucTe).Take(100).ToListAsync();return View(new PhieuPhat{MaPhieuPhat="PP"+DateTime.Now.ToString("yyyyMMddHHmmss"),NgayLap=DateTime.Now,TrangThai="CHUA_THANH_TOAN"});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(PhieuPhat x){if(await _db.PhieuPhat.AnyAsync(p=>p.MaPhieuPhat==x.MaPhieuPhat))ModelState.AddModelError("MaPhieuPhat","Mã phiếu phạt đã tồn tại.");if(x.SoTien<0)ModelState.AddModelError("SoTien","Số tiền không hợp lệ.");if(!ModelState.IsValid){ViewBag.ChiTiet=await _db.ChiTietHopDong.Take(100).ToListAsync();return View(x);}_db.PhieuPhat.Add(x);await _db.SaveChangesAsync();TempData["Ok"]="Đã lập phiếu phạt.";return RedirectToAction("Index");}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>SetStatus(string id,string status){var x=await _db.PhieuPhat.FindAsync(id);if(x==null)return NotFound();x.TrangThai=status;await _db.SaveChangesAsync();TempData["Ok"]="Đã cập nhật trạng thái phiếu phạt.";return RedirectToAction("Index");}}
public class PenaltyRowVM{public PhieuPhat Phieu{get;set;}=new();public string MaHopDong{get;set;}="";public string MaThietBi{get;set;}="";}
